CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER CHECK(c0 IS NULL OR length(c0) < 40), c1 BLOB NOT NULL DEFAULT 0, c2 REAL NOT NULL DEFAULT 0, c3 BLOB CHECK(c3 IS NULL OR length(c3) < 40), c4 VARCHAR(10));
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(x'3a76', -9223372036854775808, 383, 'pi', 5);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 BLOB UNIQUE, c1 NUMERIC COLLATE NOCASE, c2 INTEGER NOT NULL DEFAULT 0, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, ref) VALUES(-368, x'45b9d4489a3c', 4.5e-310, 6);
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', 0, 1), instr('gamma', 'Lambda'), replace('gamma', '', '_'), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE 'a%', 'gamma' GLOB '*', char(80, 979), 'gamma' || 'Lambda', 'gamma' < 'Lambda', 'gamma' = 'Lambda' COLLATE NOCASE;
SELECT length(''), upper(''), lower(''), substr('', 2, 2), instr('', 'MU'), replace('', '', 'XY'), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE 'A%', '' GLOB '*[a-m]*', char(75, 453), '' || 'MU', '' < 'MU', '' = 'MU' COLLATE NOCASE;
SELECT length('delta'), upper('delta'), lower('delta'), substr('delta', -1, 5), instr('delta', ' pad '), replace('delta', '', 'XY'), trim('delta'), ltrim('delta', 'ab'), hex('delta'), quote('delta'), unicode('delta'), 'delta' LIKE 'A%', 'delta' GLOB '?', char(79, 681), 'delta' || ' pad ', 'delta' < ' pad ', 'delta' = ' pad ' COLLATE NOCASE;
SELECT length('rho'), upper('rho'), lower('rho'), substr('rho', 0, 4), instr('rho', 'chi'), replace('rho', '', ''), trim('rho'), ltrim('rho', 'ab'), hex('rho'), quote('rho'), unicode('rho'), 'rho' LIKE '%é%', 'rho' GLOB 'a*', char(67, 602), 'rho' || 'chi', 'rho' < 'chi', 'rho' = 'chi' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', 3, 4), instr('omega', 'chi'), replace('omega', 'e', 'XY'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '%a_', 'omega' GLOB '?', char(90, 726), 'omega' || 'chi', 'omega' < 'chi', 'omega' = 'chi' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 3, 3), instr('phi', 'xi'), replace('phi', 'é', 'XY'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '_', 'phi' GLOB '*[a-m]*', char(81, 983), 'phi' || 'xi', 'phi' < 'xi', 'phi' = 'xi' COLLATE NOCASE;
CREATE INDEX IF NOT EXISTS i0 ON t1(id, id) WHERE id IS NOT NULL;
SELECT id, id FROM t1 WHERE id <= 'xi' ORDER BY id, id;
SELECT count(*) FROM t1 INDEXED BY i0 WHERE id IS NOT NULL;
REINDEX t1;
DROP INDEX IF EXISTS i0;
SELECT id, NOT nullif(coalesce(x'', c0), coalesce(1, c0)), c1 FROM t1 ORDER BY id, c0, c1 DESC, c2 DESC, ref;
SELECT NULL BETWEEN NULL AND coalesce('delta', 'naïve') BETWEEN CASE WHEN 'upsilon' THEN 'epsilon' ELSE x'c04ea9cf80' END AND 'Lambda', (typeof(NULL) AND iif(2, NULL, x'76e4')) IN (-(NULL), 'phi', 'tau');
SELECT count(*), count(c3), sum(c3), total(c3), avg(c3), min(c3), max(c3), count(DISTINCT c3) FROM t0;
SELECT c3, count(*), group_concat(id, ';') FROM (SELECT * FROM t0 ORDER BY id) GROUP BY c3 HAVING count(*) > 1 ORDER BY c3;
